class Solution {
  public int sumOfPrimesInRange(int n) {
    int r = Integer.parseInt(new StringBuilder(Integer.toString(n)).reverse().toString());
    int lo = Math.min(n, r), hi = Math.max(n, r), sum = 0;
    for (int x = Math.max(2, lo); x <= hi; x++) {
      boolean prime = true;
      for (int d = 2; d * d <= x; d++) {
        if (x % d == 0) {
          prime = false;
          break;
        }
      }
      if (prime) sum += x;
    }
    return sum;
  }
}
